148	/// Used to create a new [`ThreadPool`] or to configure the global rayon thread pool.
149	/// ## Creating a ThreadPool
150	/// The following creates a thread pool with 22 threads.
151	///
152	/// ```ignore-wasm
153	/// # use rayon_core as rayon;
154	/// let pool = rayon::ThreadPoolBuilder::new().num_threads(22).build().unwrap();
155	/// ```
156	///
157	/// To instead configure the global thread pool, use [`build_global()`]:
158	///
159	/// ```ignore-wasm
160	/// # use rayon_core as rayon;
161	/// rayon::ThreadPoolBuilder::new().num_threads(22).build_global().unwrap();
162	/// ```
163	///
164	/// [`build_global()`]: Self::build_global()
165	pub struct ThreadPoolBuilder<S = DefaultSpawn> {
166	    /// The number of threads in the rayon thread pool.
167	    /// If zero will use the RAYON_NUM_THREADS environment variable.
168	    /// If RAYON_NUM_THREADS is invalid or zero will use the default.
169	    num_threads: usize,
170	
171	    /// The thread we're building *from* will also be part of the pool.
172	    use_current_thread: bool,
173	
174	    /// Custom closure, if any, to handle a panic that we cannot propagate
175	    /// anywhere else.
176	    panic_handler: Option<Box<PanicHandler>>,
177	
178	    /// Closure to compute the name of a thread.
179	    get_thread_name: Option<Box<dyn FnMut(usize) -> String>>,
180	
181	    /// The stack size for the created worker threads
182	    stack_size: Option<usize>,
183	
184	    /// Closure invoked on worker-thread start.
185	    start_handler: Option<Box<StartHandler>>,
186	
187	    /// Closure invoked on worker-thread exit.
188	    exit_handler: Option<Box<ExitHandler>>,
189	
190	    /// Closure invoked to spawn threads.
191	    spawn_handler: S,
192	
193	    /// If false, worker threads will execute spawned jobs in a
194	    /// "depth-first" fashion. If true, they will do a "breadth-first"
195	    /// fashion. Depth-first is the default.
196	    breadth_first: bool,
197	}
