199	/// Contains the rayon thread pool configuration. Use [`ThreadPoolBuilder`] instead.
200	#[deprecated(note = "Use `ThreadPoolBuilder`")]
201	#[derive(Default)]
202	pub struct Configuration {
203	    builder: ThreadPoolBuilder,
204	}
