244	/// Note: the `S: ThreadSpawn` constraint is an internal implementation detail for the
245	/// default spawn and those set by [`spawn_handler`](#method.spawn_handler).
246	#[expect(private_bounds)]
247	impl<S> ThreadPoolBuilder<S>
248	where
249	    S: ThreadSpawn,
250	{
251	    /// Creates a new `ThreadPool` initialized using this configuration.
252	    pub fn build(self) -> Result<ThreadPool, ThreadPoolBuildError> {
253	        ThreadPool::build(self)
254	    }
255	
256	    /// Initializes the global thread pool. This initialization is
257	    /// **optional**.  If you do not call this function, the thread pool
258	    /// will be automatically initialized with the default
259	    /// configuration. Calling `build_global` is not recommended, except
260	    /// in two scenarios:
261	    ///
262	    /// - You wish to change the default configuration.
263	    /// - You are running a benchmark, in which case initializing may
264	    ///   yield slightly more consistent results, since the worker threads
265	    ///   will already be ready to go even in the first iteration.  But
266	    ///   this cost is minimal.
267	    ///
268	    /// Initialization of the global thread pool happens exactly
269	    /// once. Once started, the configuration cannot be
270	    /// changed. Therefore, if you call `build_global` a second time, it
271	    /// will return an error. An `Ok` result indicates that this
272	    /// is the first initialization of the thread pool.
273	    pub fn build_global(self) -> Result<(), ThreadPoolBuildError> {
274	        let registry = registry::init_global_registry(self)?;
275	        registry.wait_until_primed();
276	        Ok(())
277	    }
278	}
