342	impl<S> ThreadPoolBuilder<S> {
343	    /// Sets a custom function for spawning threads.
344	    ///
345	    /// Note that the threads will not exit until after the pool is dropped. It
346	    /// is up to the caller to wait for thread termination if that is important
347	    /// for any invariants. For instance, threads created in [`std::thread::scope`]
348	    /// will be joined before that scope returns, and this will block indefinitely
349	    /// if the pool is leaked. Furthermore, the global thread pool doesn't terminate
350	    /// until the entire process exits!
351	    ///
352	    /// # Examples
353	    ///
354	    /// A minimal spawn handler just needs to call `run()` from an independent thread.
355	    ///
356	    /// ```ignore-wasm
357	    /// # use rayon_core as rayon;
358	    /// fn main() -> Result<(), rayon::ThreadPoolBuildError> {
359	    ///     let pool = rayon::ThreadPoolBuilder::new()
360	    ///         .spawn_handler(|thread| {
361	    ///             std::thread::spawn(|| thread.run());
362	    ///             Ok(())
363	    ///         })
364	    ///         .build()?;
365	    ///
366	    ///     pool.install(|| println!("Hello from my custom thread!"));
367	    ///     Ok(())
368	    /// }
369	    /// ```
370	    ///
371	    /// The default spawn handler sets the name and stack size if given, and propagates
372	    /// any errors from the thread builder.
373	    ///
374	    /// ```ignore-wasm
375	    /// # use rayon_core as rayon;
376	    /// fn main() -> Result<(), rayon::ThreadPoolBuildError> {
377	    ///     let pool = rayon::ThreadPoolBuilder::new()
378	    ///         .spawn_handler(|thread| {
379	    ///             let mut b = std::thread::Builder::new();
380	    ///             if let Some(name) = thread.name() {
381	    ///                 b = b.name(name.to_owned());
382	    ///             }
383	    ///             if let Some(stack_size) = thread.stack_size() {
384	    ///                 b = b.stack_size(stack_size);
385	    ///             }
386	    ///             b.spawn(|| thread.run())?;
387	    ///             Ok(())
388	    ///         })
389	    ///         .build()?;
390	    ///
391	    ///     pool.install(|| println!("Hello from my fully custom thread!"));
392	    ///     Ok(())
393	    /// }
394	    /// ```
395	    ///
396	    /// This can also be used for a pool of scoped threads like [`crossbeam::scope`],
397	    /// or [`std::thread::scope`] introduced in Rust 1.63, which is encapsulated in
398	    /// [`build_scoped`].
399	    ///
400	    /// [`crossbeam::scope`]: https://docs.rs/crossbeam/0.8/crossbeam/fn.scope.html
401	    /// [`build_scoped`]: Self::build_scoped()
402	    ///
403	    /// ```ignore-wasm
404	    /// # use rayon_core as rayon;
405	    /// fn main() -> Result<(), rayon::ThreadPoolBuildError> {
406	    ///     std::thread::scope(|scope| {
407	    ///         let pool = rayon::ThreadPoolBuilder::new()
408	    ///             .spawn_handler(|thread| {
409	    ///                 let mut builder = std::thread::Builder::new();
410	    ///                 if let Some(name) = thread.name() {
411	    ///                     builder = builder.name(name.to_string());
412	    ///                 }
413	    ///                 if let Some(size) = thread.stack_size() {
414	    ///                     builder = builder.stack_size(size);
415	    ///                 }
416	    ///                 builder.spawn_scoped(scope, || {
417	    ///                     // Add any scoped initialization here, then run!
418	    ///                     thread.run()
419	    ///                 })?;
420	    ///                 Ok(())
421	    ///             })
422	    ///             .build()?;
423	    ///
424	    ///         pool.install(|| println!("Hello from my custom scoped thread!"));
425	    ///         Ok(())
426	    ///     })
427	    /// }
428	    /// ```
429	    pub fn spawn_handler<F>(self, spawn: F) -> ThreadPoolBuilder<CustomSpawn<F>>
430	    where
431	        F: FnMut(ThreadBuilder) -> io::Result<()>,
432	    {
433	        ThreadPoolBuilder {
434	            spawn_handler: CustomSpawn::new(spawn),
435	            // ..self
436	            num_threads: self.num_threads,
437	            use_current_thread: self.use_current_thread,
438	            panic_handler: self.panic_handler,
439	            get_thread_name: self.get_thread_name,
440	            stack_size: self.stack_size,
441	            start_handler: self.start_handler,
442	            exit_handler: self.exit_handler,
443	            breadth_first: self.breadth_first,
444	        }
445	    }
446	
447	    /// Returns a reference to the current spawn handler.
448	    fn get_spawn_handler(&mut self) -> &mut S {
449	        &mut self.spawn_handler
450	    }
451	
452	    /// Get the number of threads that will be used for the thread
453	    /// pool. See `num_threads()` for more information.
454	    fn get_num_threads(&self) -> usize {
455	        if self.num_threads > 0 {
456	            self.num_threads
457	        } else {
458	            let default = || {
459	                thread::available_parallelism()
460	                    .map(|n| n.get())
461	                    .unwrap_or(1)
462	            };
463	
464	            match env::var("RAYON_NUM_THREADS")
465	                .ok()
466	                .and_then(|s| usize::from_str(&s).ok())
467	            {
468	                Some(x @ 1..) => return x,
469	                Some(0) => return default(),
470	                _ => {}
471	            }
472	
473	            // Support for deprecated `RAYON_RS_NUM_CPUS`.
474	            match env::var("RAYON_RS_NUM_CPUS")
475	                .ok()
476	                .and_then(|s| usize::from_str(&s).ok())
477	            {
478	                Some(x @ 1..) => x,
479	                _ => default(),
480	            }
481	        }
482	    }
483	
484	    /// Get the thread name for the thread with the given index.
485	    fn get_thread_name(&mut self, index: usize) -> Option<String> {
486	        let f = self.get_thread_name.as_mut()?;
487	        Some(f(index))
488	    }
489	
490	    /// Sets a closure which takes a thread index and returns
491	    /// the thread's name.
492	    pub fn thread_name<F>(mut self, closure: F) -> Self
493	    where
494	        F: FnMut(usize) -> String + 'static,
495	    {
496	        self.get_thread_name = Some(Box::new(closure));
497	        self
498	    }
499	
500	    /// Sets the number of threads to be used in the rayon thread pool.
501	    ///
502	    /// If you specify a non-zero number of threads using this
503	    /// function, then the resulting thread pools are guaranteed to
504	    /// start at most this number of threads.
505	    ///
506	    /// If `num_threads` is 0, or you do not call this function, then
507	    /// the Rayon runtime will select the number of threads
508	    /// automatically. At present, this is based on the
509	    /// `RAYON_NUM_THREADS` environment variable (if set),
510	    /// or the number of logical CPUs (otherwise).
511	    /// In the future, however, the default behavior may
512	    /// change to dynamically add or remove threads as needed.
513	    ///
514	    /// **Future compatibility warning:** Given the default behavior
515	    /// may change in the future, if you wish to rely on a fixed
516	    /// number of threads, you should use this function to specify
517	    /// that number. To reproduce the current default behavior, you
518	    /// may wish to use [`std::thread::available_parallelism`]
519	    /// to query the number of CPUs dynamically.
520	    ///
521	    /// **Old environment variable:** `RAYON_NUM_THREADS` is a one-to-one
522	    /// replacement of the now deprecated `RAYON_RS_NUM_CPUS` environment
523	    /// variable. If both variables are specified, `RAYON_NUM_THREADS` will
524	    /// be preferred.
525	    pub fn num_threads(mut self, num_threads: usize) -> Self {
526	        self.num_threads = num_threads;
527	        self
528	    }
529	
530	    /// Use the current thread as one of the threads in the pool.
531	    ///
532	    /// The current thread is guaranteed to be at index 0, and since the thread is not managed by
533	    /// rayon, the spawn and exit handlers do not run for that thread.
534	    ///
535	    /// Note that the current thread won't run the main work-stealing loop, so jobs spawned into
536	    /// the thread pool will generally not be picked up automatically by this thread unless you
537	    /// yield to rayon in some way, like via [`yield_now()`], [`yield_local()`], or [`scope()`].
538	    ///
539	    /// # Local thread pools
540	    ///
541	    /// Using this in a local thread pool means the registry will be leaked. In future versions
542	    /// there might be a way of cleaning up the current-thread state.
543	    pub fn use_current_thread(mut self) -> Self {
544	        self.use_current_thread = true;
545	        self
546	    }
547	
548	    /// Returns a copy of the current panic handler.
549	    fn take_panic_handler(&mut self) -> Option<Box<PanicHandler>> {
550	        self.panic_handler.take()
551	    }
552	
553	    /// Normally, whenever Rayon catches a panic, it tries to
554	    /// propagate it to someplace sensible, to try and reflect the
555	    /// semantics of sequential execution. But in some cases,
556	    /// particularly with the `spawn()` APIs, there is no
557	    /// obvious place where we should propagate the panic to.
