564	    /// If the panic handler itself panics, this will abort the
565	    /// process. To prevent this, wrap the body of your panic handler
566	    /// in a call to `std::panic::catch_unwind()`.
567	    pub fn panic_handler<H>(mut self, panic_handler: H) -> Self
568	    where
569	        H: Fn(Box<dyn Any + Send>) + Send + Sync + 'static,
